package com.app.service;

import com.app.dto.UserRegistrationDTO;
import com.app.exception.EmailAlreadyExistsException;
import com.app.model.User;
import com.app.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class UserService {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;

    @Transactional
    public User registerUser(UserRegistrationDTO registrationDTO) {

        // Step 1: Check for duplicate email
        if (userRepository.existsByEmail(registrationDTO.getEmail().toLowerCase())) {
            log.warn("Registration attempt with existing email: {}",
                     registrationDTO.getEmail());
            throw new EmailAlreadyExistsException(
                "An account with this email already exists"
            );
        }

        // Step 2: Build user entity
        User newUser = new User();
        newUser.setName(registrationDTO.getName().trim());
        newUser.setEmail(registrationDTO.getEmail().toLowerCase().trim());

        // Step 3: CRITICAL - Hash password with BCrypt (never store plain text)
        newUser.setPasswordHash(
            passwordEncoder.encode(registrationDTO.getPassword())
        );

        // Step 4: Persist to database
        User savedUser = userRepository.save(newUser);

        log.info("New user registered successfully. ID: {}", savedUser.getId());
        return savedUser;
    }
}
```

