# Binary String XOR Query Solver in Object Pascal

## Problem Analysis

The core challenge is: for each query `[first, second]`, find the shortest substring of binary string `s` whose decimal value `val` satisfies `val XOR first = second`. Since `val XOR first = second`, then `val = first XOR second`.

**Key Insights:**
1. The target value for each query is simply `first XOR second`
2. We need the **shortest** substring, and among equal lengths, the **leftmost** one
3. We can precompute all possible substring values mapped to their `[left, right]` endpoints for efficiency
4. Since `s.length <= 10^4`, values representable by substrings are bounded by the number of bits

## Solution Strategy

- **Precompute** a map from decimal values → best `[left, right]` (shortest, then leftmost)
- Iterate over all substrings, compute their decimal values
- For values exceeding `10^9` (max constraint), skip them (too large to be a valid target)
- Answer each query in O(1) using the precomputed map

```pascal
program BinaryStringXORQueries;

{$mode objfpc}{$H+}

uses
  SysUtils, Classes, fgl;

type
  TIntPair = array[0..1] of Integer;
  TIntPairArray = array of TIntPair;
  // Map: Integer -> TIntPair (stores best [left, right] for each decimal value)
  TValueMap = specialize TFPGMap<Int64, TIntPair>;

function SolveQueries(const s: string; const queries: TIntPairArray): TIntPairArray;
var
  ValueMap: TValueMap;
  n, i, j: Integer;
  val: Int64;
  target: Int64;
  idx: Integer;
  bestPair, currentPair: TIntPair;
  currentLen, bestLen: Integer;
  noResult: TIntPair;
  charVal: Integer;
const
  MAX_VAL = Int64(1000000000); // 10^9 per constraints
begin
  n := Length(s);
  ValueMap := TValueMap.Create;
  ValueMap.Sorted := True;

  noResult[0] := -1;
  noResult[1] := -1;

  try
    // Precompute all substring decimal values
    // Outer loop: start index (0-based, but Pascal strings are 1-based)
    for i := 1 to n do
    begin
      val := 0;
      for j := i to n do
      begin
        // Build value bit by bit (left to right = most significant first)
        if s[j] = '1' then
          charVal := 1
        else
          charVal := 0;

        val := (val shl 1) or charVal;

        // Skip values exceeding our constraint maximum
        if val > MAX_VAL then
          Break;

        // Current substring: 0-indexed [i-1, j-1], length = j - i + 1
        currentPair[0] := i - 1;
        currentPair[1] := j - 1;
        currentLen := j - i + 1;

        idx := ValueMap.IndexOf(val);
        if idx < 0 then
        begin
          // New value: add it
          ValueMap.Add(val, currentPair);
        end
        else
        begin
          // Existing value: check if current is shorter, or same length but more left
          bestPair := ValueMap.Data[idx];
          bestLen := bestPair[1] - bestPair[0] + 1;

          if (currentLen < bestLen) or
             ((currentLen = bestLen) and (currentPair[0] < bestPair[0])) then
          begin
            ValueMap.Data[idx] := currentPair;
          end;
        end;
      end;
    end;

    // Answer each query
    SetLength(Result, Length(queries));
    for i := 0 to High(queries) do
    begin
      // Target value = first XOR second
      target := Int64(queries[i][0]) xor Int64(queries[i][1]);

      if target > MAX_VAL then
      begin
        Result[i] := noResult;
        Continue;
      end;

      idx := ValueMap.IndexOf(target);
      if idx >= 0 then
        Result[i] := ValueMap.Data[idx]
      else
        Result[i] := noResult;
    end;

  finally
    ValueMap.Free;
  end;
end;

// ─── Test Harness ────────────────────────────────────────────────────────────

procedure PrintResults(const results: TIntPairArray);
var
  i: Integer;
begin
  Write('[');
  for i := 0 to High(results) do
  begin
    Write('[', results[i][0], ',', results[i][1], ']');
    if i < High(results) then Write(',');
  end;
  WriteLn(']');
end;

var
  queries: TIntPairArray;
  results: TIntPairArray;
begin
  WriteLn('=== Example 1 ===');
  // s = "101101", queries = [[0,5],[1,2]]
  SetLength(queries, 2);
  queries[0][0] := 0;  queries[0][1] := 5;
  queries[1][0] := 1;  queries[1][1] := 2;
  results := SolveQueries('101101', queries);
  Write('Output: ');
  PrintResults(results);
  WriteLn('Expected: [[0,2],[2,3]]');
  WriteLn;

  WriteLn('=== Example 2 ===');
  // s = "0101", queries = [[12,8]]
  SetLength(queries, 1);
  queries[0][0] := 12; queries[0][1] := 8;
  results := SolveQueries('0101', queries);
  Write('Output: ');
  PrintResults(results);
  WriteLn('Expected: [[-1,-1]]');
  WriteLn;

  WriteLn('=== Example 3 ===');
  // s = "1", queries = [[4,5]]
  SetLength(queries, 1);
  queries[0][0] := 4;  queries[0][1] := 5;
  results := SolveQueries('1', queries);
  Write('Output: ');
  PrintResults(results);
  WriteLn('Expected: [[0,0]]');
end.
```

## Complexity Analysis

| Aspect | Complexity | Notes |
|--------|-----------|-------|
| **Precomputation** | O(n × log(MAX_VAL)) | At most 30 bits per start position |
| **Query answering** | O(Q × log(n)) | Map lookup per query |
| **Space** | O(n × log(MAX_VAL)) | Bounded map entries |

## Key Design Decisions

1. **XOR Inversion**: Since `val XOR first = second` → `val = first XOR second`, we reduce each query to a simple value lookup
2. **Early Termination**: Once a substring value exceeds `10^9`, we break the inner loop (values only grow as we extend right)
3. **Best Pair Selection**: We prefer shorter substrings, then leftmost start index
4. **Int64 Safety**: Using `Int64` prevents overflow during bit-shift operations on large substrings

# Swift Translation & Analysis

## Translated Swift Code

```swift
import Foundation

// MARK: - Helper Function: Generate All Substrings
func allSubstrings(_ inputString: String) -> [String] {
    let characters = Array(inputString) // Convert to array for index-based access
    let length = characters.count
    var substrings: [String] = []

    for i in 0..<length {
        for j in (i + 1)...length {
            let substring = String(characters[i..<j])
            substrings.append(substring)
        }
    }
    return substrings
}

// MARK: - Core Function: Find Longest Common Substring
func longestSubstring(_ strings: [String], _ k: Int) -> String? {
    // Guard against empty input - mirrors Python's None return
    guard !strings.isEmpty else { return nil }

    var longestStr = ""

    for s in strings {
        for substr in allSubstrings(s) {
            // Count how many strings in the array contain this substring
            let count = strings.filter { $0.contains(substr) }.count

            // Update longest if frequency threshold is met and length exceeds current best
            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }
    // Return nil if no valid substring found, otherwise return result
    return longestStr.isEmpty ? nil : longestStr
}

// MARK: - Example Usage
let testStrings = ["apple", "pineapple", "snapple", "grapple"]
let k = 3

if let result = longestSubstring(testStrings, k) {
    print("Longest common substring (appearing in at least \(k) strings): '\(result)'")
} else {
    print("No common substring found.")
}
```

---

## How The Code Works: A Breakdown

### 1. `allSubstrings(_ inputString: String) -> [String]`

```
Input: "cat"
Output: ["c", "ca", "cat", "a", "at", "t"]
```

| Step | What Happens |
|------|-------------|
| `Array(inputString)` | Converts String to `[Character]` for safe index access |
| Outer loop `i` | Marks the **start** of each substring |
| Inner loop `j` | Marks the **end** of each substring |
| `characters[i..<j]` | Slices the character array and builds a String |

> **Why convert to Array?** Swift Strings don't support integer-based indexing directly (unlike Python). Converting to a `[Character]` array allows clean `[i..<j]` slicing.

---

### 2. `longestSubstring(_ strings: [String], _ k: Int) -> String?`

```
Input: ["apple", "pineapple", "snapple"], k = 2
Output: "apple"
```

| Step | What Happens |
|------|-------------|
| `guard !strings.isEmpty` | Early exit returning `nil` if input is empty |
| Nested loops | Every substring of every string is evaluated |
| `.filter { $0.contains(substr) }.count` | Counts how many strings contain the substring |
| `count >= k` | Checks if the frequency **threshold** is satisfied |
| `substr.count > longestStr.count` | Ensures we only keep the **longest** valid match |
| `return longestStr.isEmpty ? nil : longestStr` | Returns `nil` if no valid match was found |

---

### Key Swift vs Python Differences

| Concept | Python | Swift |
|---------|--------|-------|
| Optional return | `None` | `nil` / `Optional<String>` |
| Null safety check | `if len(strings) == 0` | `guard !strings.isEmpty` |
| Count matching | `sum(x in y for y in list)` | `.filter { $0.contains(x) }.count` |
| String slicing | `string[i:j]` | `String(characters[i..<j])` |
| Type annotations | `List[str]`, `Optional[str]` | `[String]`, `String?` |

---

### Time Complexity Warning ⚠️

> This algorithm runs at **O(n × m² × n × m)** where `n` = number of strings and `m` = average string length. For large datasets, consider a **suffix tree or trie-based approach** to dramatically improve performance.

# Business Problem Analysis & Solution

## Breaking Down the Problem

Before diving into code, let me systematically analyze the sorting requirements:

1. **Numbers before letters** (case-sensitive sort)
2. **Same starting character** → sort by **length descending**
3. **Same starting character + length** → sort by **ASCII value descending**
4. **Same starting character + length + ASCII** → **preserve original order** (stable sort)

---

## Solution Implementation

```javascript
/**
 * Sorts books according to custom sorting rules:
 * 1. Numbers before letters (case-sensitive)
 * 2. Same first char → longer books first (descending length)
 * 3. Same first char + length → higher ASCII value first
 * 4. Same first char + length + ASCII → preserve original order (stable)
 *
 * @param {string[]} books - Array of book title strings
 * @returns {string[]} - New sorted array of book titles
 */
function sortBooks(books) {
  // Input validation - defensive programming
  if (!Array.isArray(books) || books.length === 0) {
    throw new Error("Input must be a non-empty array.");
  }

  // Step 1: Tag each book with its original index to ensure stable sort
  // This is critical because JavaScript's sort is not guaranteed stable in all environments
  const indexedBooks = books.map((book, index) => ({ book, index }));

  // Step 2: Define a helper to determine if a character is a digit
  const isDigit = (char) => char >= "0" && char <= "9";

  // Step 3: Define a helper to determine sort priority of first character
  // Numbers (0-9) come before letters and special characters
  const getCharPriority = (char) => {
    if (isDigit(char)) return 0; // Digits have highest priority (come first)
    return 1;                    // All other characters come after
  };

  // Step 4: Core comparison function implementing all business rules
  const comparator = (a, b) => {
    const bookA = a.book;
    const bookB = b.book;

    const firstCharA = bookA[0];
    const firstCharB = bookB[0];

    // --- Rule 1: Numbers before letters ---
    const priorityA = getCharPriority(firstCharA);
    const priorityB = getCharPriority(firstCharB);

    if (priorityA !== priorityB) {
      return priorityA - priorityB; // Lower priority value = comes first
    }

    // --- Both start with same type (both digits OR both non-digits) ---
    // Now apply standard case-sensitive alphabetical comparison on first character
    if (firstCharA !== firstCharB) {
      // Case-sensitive: uppercase 'A' (65) comes before lowercase 'a' (97)
      return firstCharA < firstCharB ? -1 : 1;
    }

    // --- Rule 2: Same first character → sort by LENGTH descending ---
    if (bookA.length !== bookB.length) {
      return bookB.length - bookA.length; // Longer books come first
    }

    // --- Rule 3: Same first character + length → sort by ASCII value descending ---
    // Compare full string ASCII value by iterating character by character
    for (let i = 0; i < bookA.length; i++) {
      const asciiA = bookA.charCodeAt(i);
      const asciiB = bookB.charCodeAt(i);

      if (asciiA !== asciiB) {
        return asciiB - asciiA; // Higher ASCII value comes first (descending)
      }
    }

    // --- Rule 4: Same first char + length + ASCII → preserve original order ---
    return a.index - b.index; // Stable sort fallback using original index
  };

  // Step 5: Sort and extract just the book titles
  return indexedBooks.sort(comparator).map(({ book }) => book);
}

// ─────────────────────────────────────────────
// TEST CASES
