## Step 6: Controllers (Business Logic)

**`controllers/blogPostController.js`**
```javascript
const BlogPost = require('../models/BlogPost');

// ─── GET ALL POSTS ───────────────────────────────────────────────────────────
const getAllPosts = async (req, res, next) => {
  try {
    // Support pagination for scalability
    const page  = parseInt(req.query.page)  || 1;
    const limit = parseInt(req.query.limit) || 10;
    const skip  = (page - 1) * limit;

    const [posts, total] = await Promise.all([
      BlogPost.find()
        .sort({ createdAt: -1 }) // Newest first
        .skip(skip)
        .limit(limit)
        .select('title text author createdAt'), // Explicit field selection
      BlogPost.countDocuments(),
    ]);

    res.status(200).json({
      success: true,
      count: posts.length,
      total,
      page,
      totalPages: Math.ceil(total / limit),
      data: posts,
    });
  } catch (error) {
    next(error);
  }
};

// ─── GET SINGLE POST ─────────────────────────────────────────────────────────
const getPostById = async (req, res, next) => {
  try {
    const post = await BlogPost.findById(req.params.id);

    if (!post) {
      return res.status(404).json({
        success: false,
        message: `Post with ID ${req.params.id} not found`,
      });
    }

    res.status(200).json({ success: true, data: post });
  } catch (error) {
    next(error);
  }
};

// ─── CREATE POST ─────────────────────────────────────────────────────────────
const createPost = async (req, res, next) => {
  try {
    const { title, text, author } = req.body;

    const post = await BlogPost.create({ title, text, author });

    res.status(201).json({
      success: true,
      message: 'Blog post created successfully',
      data: post,
    });
  } catch (error) {
    next(error);
  }
};

// ─── UPDATE POST ─────────────────────────────────────────────────────────────
const updatePost = async (req, res, next) => {
  try {
    const { title, text, author } = req.body;

    const post = await BlogPost.findByIdAndUpdate(
      req.params.id,
      { title, text, author },
      {
        new: true,           // Return updated document
        runValidators: true, // Enforce schema validation on update
      }
    );

    if (!post) {
      return res.status(404).json({
        success: false,
        message: `Post with ID ${req.params.id} not found`,
      });
    }

    res.status(200).json({
      success: true,
      message: 'Blog post updated successfully',
      data: post,
    });
  } catch (error) {
    next(error);
  }
};

// ─── DELETE POST ─────────────────────────────────────────────────────────────
const deletePost = async (req, res, next) => {
  try {
    const post = await BlogPost.findByIdAndDelete(req.params.id);

    if (!post) {
      return res.status(404).json({
        success: false,
        message: `Post with ID ${req.params.id} not found`,
      });
    }

    res.status(200).json({
      success: true,
      message: 'Blog post deleted successfully',
    });
  } catch (error) {
    next(error);
  }
};

module.exports = {
  getAllPosts,
  getPostById,
  createPost,
  updatePost,
  deletePost,
};
```

