## Step 7: Routes

**`routes/blogPostRoutes.js`**
```javascript
const express = require('express');
const router  = express.Router();

const {
  getAllPosts,
  getPostById,
  createPost,
  updatePost,
  deletePost,
} = require('../controllers/blogPostController');

// ─── ROUTE DEFINITIONS ───────────────────────────────────────────────────────
router.route('/')
  .get(getAllPosts)    // GET  /api/posts
  .post(createPost);  // POST /api/posts

router.route('/:id')
  .get(getPostById)    // GET    /api/posts/:id
  .put(updatePost)     // PUT    /api/posts/:id
  .delete(deletePost); // DELETE /api/posts/:id

module.exports = router;
```

